INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65369512', 65369512, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan Junior Penyusunan Dokumen Analisis Pengembangan Rencana Pembangunan Wilayah untuk Mendukung ASEAN Connectivity Strategic Plan (ACSP)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', '7. Lingkup Pekerjaan 1. Memberikan masukan terhadap review evaluasi pelaksanaan pembangunan kegiatan-kegiatan prioritas rencana pembangunan wilayah secara umum; 2. Memberikan masukan terhadap review kerangka evaluasi dan arahan pelaksanaan pengembangan rencana pembangunan wilayah yang mendukung ASEAN Connectivity Strategic Plan (ACSP); 3. Membantu terhadap analisis terkait update implementasi mencakup perumusan masalah dan skala prioritas terkait kegiatan rencana pembangunan wilayah yang mendukung kegiatan ACSP; 4. Membantu terhadap analisis pengembangan rencana pembangunan wilayah, khususnya yang mendukung kegiatan ACSP; 5. Memberikan masukan identifikasi strategi untuk mengintegrasikan kegiatan khusus dalam hal rencana pembangunan wilayah yang mendukung implementasi kegaitan ACSP.', '1. Diutamakan menggunakan Asisten Konsultan dalam Negeri, dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk (KTP); 2. Memiliki Nomor Pokok Wajib Pajak (NPWP); 3. Pendidikan minimal S1 bidang perencanaan dan pembangunan atau bidang teknik (melampirkan bukti ijazah); 4. Memiliki pengalaman kerja di sektor transportasi, infrastruktur logistik, dan/atau perencanaan pembangunan minimal 1-2 Tahun, dibuktikan dengan kontrak/surat keterangan kerja sebelumnya; 5. Memiliki pengalaman dalam penyusunan laporan, notulensi, analisis data dasar, serta dokumentasi kegiatan. 6. Memiliki pengalaman dalam koordinasi kegiatan, rapat, dan komunikasi dengan pemangku kepentingan (stakeholder) pada sektor transportasi. 7. Memiliki kemampuan dalam penyusunan policy brief, materi presentasi, dan narasi kebijakan untuk mendukung diseminasi program transportasi dan konektivitas ASEAN; 8. Memiliki sertifikat pelatihan/workshop/seminar yang relevan (jika ada). 9. Memiliki kemampuan komunikasi lisan maupun tulisan yang baik, disiplin, dan mampu bekerja dalam tim, serta kemampuan mengolah dan menyajikan data dalam format visual yang menarik.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2090613);
