INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65341122', 65341122, 'analyze_legacy', 'Provinsi Kalimantan Timur', 'provinsi', 'Dinas Kelautan Dan Perikanan', 'Kegiatan Penyadartahuan Kepada Masyarakat tentang mitigasi bencana wilayah pesisir dan pulau-pulau kecil', 'Barang', 'E-Purchasing', 'Kalimantan Timur, Bontang (Kota)', 7079700, 'July 2026', 'APBD', 1, 1, '1 paket', 'Indonesia yang terdiri dari gugusan kepulauan mempunyai potensi bencana yang sangat tinggi dan juga sangat bervariasi dari aspek jenis bencana. Kondisi alam tersebut serta adanya keanekaragaman penduduk dan budaya di Indonesia menyebabkan timbulnya risiko terjadinya bencana alam dan bencana ulah manusia, meskipun disisi lain juga kaya akan sumberdaya alam. Bencana alam dapat terjadi kapan saja tanpa masyarakat mengetahuinya. Pada saat menghadapi bencana, masyarakat yang belum mampu untuk menanganinya sendiri harus menunggu bantuan yang kadang tidak segera dating karena adanya kendala jaraka lokasi kejadian, sedangkan pada detik-detik pertama saat bencana terjadi adalah saat yang sangat penting dalam usaha mengurangi dampak bencana yang lebih besar. Mitigasi bencana dilakukan melalui dua pendekatan, yaitu pendekatan structural dan nonstruktural. Pendekatan struktural merupakan upaya yang dilakukan dalam mengurangi dampak bencana dan perubahan iklim yang bersifat fisik, sedangkan pendeka', 'Penjilidan kegiatan,seminar kit peserta,konsumsi (Kotakan),Snack(Kudapan)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2099748);
